css:
.tr-root{position:absolute;inset:0;font-family:var(--tr-font);overflow:hidden;background:rgba(8,8,9,.94);}
.tr-mask{position:absolute;inset:0;overflow:hidden;mask-image:linear-gradient(180deg,transparent 0%,#000 10%,#000 88%,transparent 100%);-webkit-mask-image:linear-gradient(180deg,transparent 0%,#000 10%,#000 88%,transparent 100%);}
.tr-track{position:absolute;left:50%;transform:translateX(-50%);top:100%;width:840px;display:flex;flex-direction:column;gap:26px;padding:0 0 40px;animation:tr-roll var(--tr-duration) linear infinite;}
.tr-track.tr-once{animation-iteration-count:1;}
.tr-track.tr-paused{animation-play-state:paused;}
@keyframes tr-roll{from{transform:translate(-50%,0);}to{transform:translate(-50%,calc(-100% - 100vh));}}
.tr-heading{font-size:var(--tr-heading-size);font-weight:700;color:#f2f2ee;letter-spacing:5px;text-align:center;padding-bottom:14px;border-bottom:1px solid #2c2c30;}
.tr-heading:empty{display:none;}
.tr-lines{display:flex;flex-direction:column;width:100%;}
.tr-row{display:flex;align-items:baseline;gap:22px;padding:9px 0;border-bottom:1px solid #232326;}
.tr-group{font-size:var(--tr-group-size);font-weight:600;color:var(--tr-accent);letter-spacing:1.5px;width:170px;text-align:right;flex:0 0 auto;}
.tr-group:empty{display:none;}
.tr-text{font-size:var(--tr-text-size);font-weight:500;color:#e7e7e3;line-height:1.35;flex:1;min-width:0;}
.tr-logos{display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:36px;width:100%;padding-top:26px;}
.tr-logo{display:flex;align-items:center;justify-content:center;height:var(--tr-logo-h);}
.tr-logo img{height:100%;width:auto;object-fit:contain;opacity:.92;}
